package auth

import (
	"regexp"
	"testing"

	"github.com/stretchr/testify/require"
)

// pinnedVector was generated by the Node server's bcryptjs@2.4.3 at cost 12
// for "password123". It pins cross-implementation compatibility: every hash
// in the users table today came from that library.
const pinnedVector = "$2a$12$fZ75H9w8LLxU2zLabTPTE.u3khm5YBuonWj9881.yXnn1.lu3onWm"

func TestComparePassword_BcryptjsVector(t *testing.T) {
	require.True(t, ComparePassword(pinnedVector, "password123"))
	require.False(t, ComparePassword(pinnedVector, "wrong"))
}

func TestHashPassword_RoundTripAndCost(t *testing.T) {
	hash, err := HashPassword("hunter2")
	require.NoError(t, err)
	require.True(t, ComparePassword(hash, "hunter2"))
	require.False(t, ComparePassword(hash, "hunter3"))

	// $2a$ prefix (bcryptjs-readable) and cost 12 — the regexp pins both the
	// modular crypt format and the cost digits outright.
	costRe := regexp.MustCompile(`^\$2a\$12\$`)
	require.True(t, costRe.MatchString(hash), hash)
}
